    'price' => 'Цена',
    'price_pts' => 'Цена бод',
    'refund_changes' => 'Промене ове политике',
    'refund_changes_desc' => 'Задржавамо право да ажурирамо или изменимо ову Политику рефундирања у било ком тренутку. Све промене ће бити објављене на овој страници и ступити на снагу одмах по објављивању. Препоручујемо вам да периодично прегледате ову политику.',
    'refund_contact' => 'Контактирајте нас',
    'refund_contact_desc' => 'Ако имате било каквих питања у вези са овом Политиком рефундирања или желите да затражите повраћај средстава, контактирајте нас преко веб странице. Наш тим ће одговорити на све упите о повраћају новца у року од 48 сати.',
    'refund_disputes' => 'Спорови',
    'refund_disputes_desc' => 'Ако се не слажете са одлуком о повраћају новца, можете ескалирати ствар тако што ћете контактирати наш тим за подршку са додатном документацијом или доказима. Посвећени смо решавању спорова правично и брзо.',
    'refund_eligibility' => 'Подобност рефундирања',
    'refund_eligibility_desc' => 'Поврат новца се може захтевати у року од 14 дана од првобитног датума куповине, под условом да купљена услуга или претплата није у великој мери потрошена или искоришћена. Подобност утврђује наш тим од случаја до случаја.',
    'refund_intro' => 'Ова Политика рефундирања описује услове под којима се одобравају повраћаји за куповине обављене на нашој платформи. Циљ нам је да будемо фер и транспарентни у обради свих захтева за повраћај средстава.',
    'refund_last_updated' => 'Последње ажурирано',
    'refund_non_refundable' => 'Неповратне ставке',
    'refund_non_refundable_desc' => 'Одређене куповине су бесповратне, укључујући, али не ограничавајући се на: поене (ПТС) који су већ потрошени, кредите за рекламе који су потрошени, погодности претплате које су искориштене и сву дигиталну робу која је преузета или којој је приступило.',
    'refund_partial' => 'Делимични повраћаји',
    'refund_partial_desc' => 'У неким случајевима може се извршити делимичан повраћај новца ако је део купљене услуге искоришћен. Износ рефундирања ће се израчунати пропорционално на основу неискоришћеног дела услуге или периода претплате.',
    'refund_policy' => 'Политика рефундирања',
    'refund_process' => 'Како затражити повраћај новца',
    'refund_process_desc' => 'Да бисте затражили повраћај средстава, контактирајте наш тим за подршку преко веб локације са бројем поруџбине и кратким објашњењем разлога за захтев за повраћај средстава. Сви захтеви ће бити прегледани и обрађени у року од 5-7 радних дана.',
    'refund_timeframe' => 'Време обраде рефундирања',
    'refund_timeframe_desc' => 'Одобрени повраћаји се обрађују у року од 5–10 радних дана. Рефундирање ће бити враћено на првобитни начин плаћања. Имајте на уму да вашој банци или добављачу плаћања може бити потребно додатно време да прикаже повраћај средстава на вашем налогу.',
    'seo_refund_description' => 'Прочитајте нашу Политику рефундирања да бисте разумели услове под којима се одобравају повраћаји за куповине обављене на нашој платформи.',
    'privacy_changes' => 'Промене ове политике',
    'privacy_changes_desc' => 'Можемо с времена на време ажурирати ову Политику приватности. Обавестићемо вас о свим променама објављивањем нове политике на овој страници. Саветујемо вам да периодично прегледате ову Политику приватности за било какве промене.',
    'privacy_contact' => 'Контактирајте нас',
    'privacy_contact_desc' => 'Ако имате било каквих питања у вези са овом политиком приватности, контактирајте нас преко веб странице.',
    'privacy_cookies' => 'Колачићи',
    'privacy_cookies_desc' => 'Користимо колачиће и сличне технологије за праћење да бисмо сачували ваша подешавања, одржавали вашу сесију и анализирали коришћење сајта. Можете да контролишете колачиће преко подешавања вашег претраживача. Онемогућавање колачића може ограничити неке функције веб странице.',
    'privacy_data_sharing' => 'Дељење података',
    'privacy_data_sharing_desc' => 'Не продајемо, не тргујемо нити на други начин преносимо ваше личне податке трећим лицима. Можемо да делимо информације са поузданим провајдерима услуга који нам помажу у функционисању наше веб странице, пословању или пружању услуга нашим корисницима, све док се те стране слажу да ове информације чувају поверљиво.',
    'privacy_how_use' => 'Како користимо ваше информације',
    'privacy_how_use_desc' => 'Користимо информације које прикупљамо за рад и одржавање веб странице, креирање и управљање вашим налогом, обраду ваших рекламних кампања и размену посета, побољшање корисничког искуства, слање административних обавештења и спровођење наших услова и одредби.',
    'privacy_info_collect' => 'Информације које прикупљамо',
    'privacy_info_collect_desc' => 'Можемо прикупљати личне податке које нам добровољно дате када се региструјете на веб локацији, укључујући ваше корисничко име, адресу е-поште и лозинку. Такође аутоматски прикупљамо одређене информације када посетите нашу веб локацију, укључујући вашу ИП адресу, тип претраживача, оперативни систем и понашање при прегледању.',
    'privacy_intro' => 'Ваша приватност нам је важна. Ова Политика приватности објашњава како прикупљамо, користимо, откривамо и чувамо ваше податке када посетите нашу веб локацију.',
    'privacy_last_updated' => 'Последње ажурирано',
    'privacy_rights' => 'Ваша права',
    'privacy_rights_desc' => 'Имате право да приступите, ажурирате или избришете своје личне податке у било ком тренутку преко подешавања налога. Такође можете затражити копију својих података или затражити да ограничимо њихову обраду тако што ћете нас контактирати.',
    'privacy_security' => 'Сигурност података',
    'privacy_security_desc' => 'Примењујемо стандардне мере безбедности да бисмо заштитили ваше личне податке. Међутим, ниједан метод преноса преко Интернета или електронског складиштења није потпуно безбедан. Иако настојимо да заштитимо ваше податке, не можемо гарантовати њихову апсолутну сигурност.',
