    'terms_account' => 'Кориснички налози',
    'terms_account_desc' => 'Морате имати најмање 13 година да бисте направили налог. Ви сте одговорни за одржавање поверљивости акредитива вашег налога и за све активности које се дешавају под вашим налогом. Сагласни сте да ћете обезбедити тачне и потпуне информације током регистрације и да ажурирате информације о вашем налогу.',
    'terms_changes' => 'Промене Услова',
    'terms_changes_desc' => 'Задржавамо право да изменимо ове услове у било ком тренутку. Промене ће ступити на снагу одмах по објављивању на веб локацији. Ваше даље коришћење веб странице након било каквих промена представља прихватање нових услова.',
    'terms_conduct' => 'Прихватљива употреба',
    'terms_conduct_desc' => 'Сагласни сте да нећете користити веб локацију у било коју незакониту или неовлашћену сврху. Не смете да злоупотребљавате систем оглашавања, манипулишете разменом посета путем ботова или аутоматизованих алата, постављате лажан или обмањујући садржај, узнемиравате или наносите штету другим корисницима или покушавате да ометате веб локацију\\',
    'terms_contact' => 'Контактирајте нас',
    'terms_contact_desc' => 'Ако имате било каквих питања у вези са овим Одредбама и условима, контактирајте нас преко веб странице.',
    'terms_content' => 'Садржај и оглашавање',
    'terms_content_desc' => 'Ви сте искључиво одговорни за садржај који објављујете путем наших услуга оглашавања. Садржај не сме да садржи малвер, „пецање“, материјал за одрасле, говор мржње, насиље или било који садржај који крши важеће законе. Задржавамо право да уклонимо било који садржај који крши ове услове без претходног обавештења.',
    'terms_intro' => 'Приступањем и коришћењем ове веб странице прихватате и сагласни сте да будете обавезани доле наведеним одредбама и условима. Ако се не слажете са овим условима, молимо вас да не користите нашу веб страницу.',
    'terms_last_updated' => 'Последње ажурирано',
    'terms_liability' => 'Ограничење одговорности',
    'terms_liability_desc' => 'Веб локација и њене услуге се пружају \\\\"као што је\\\\" без гаранција било које врсте. Нећемо бити одговорни за било какву индиректну, случајну, посебну, последичну или казнену штету која проистиче из вашег коришћења или немогућности коришћења веб странице.',
    'terms_points' => 'Систем поена',
    'terms_points_desc' => 'Поени зарађени преко платформе су виртуелни кредити који се користе искључиво у нашем систему. Поени немају новчану вредност и не могу се заменити за готовину. Задржавамо право да изменимо систем бодова, прилагодимо вредности поена или ресетујемо поене ако се открије злоупотреба.',
    'terms_termination' => 'Укидање налога',
    'terms_termination_desc' => 'Задржавамо право да суспендујемо или укинемо ваш налог у било ком тренутку, без претходног обавештења, за понашање за које сматрамо да крши ове услове, да је штетно за друге кориснике, веб локацију или трећа лица, или из било ког другог разлога по сопственом нахођењу.',
