    'billing_gateway_flouci_restriction' => 'Доступно само у Тунису, само у ТНД',
    'billing_gateway_apple_pay' => 'Аппле Паи',
    'billing_gateway_setup_title' => 'Упутство за подешавање',
    'billing_gateway_setup_stripe' => 'Креирајте или отворите свој Стрипе налог, изаберите исти сандбок или режим уживо који се овде користи, а затим копирајте кључ за објављивање, тајни кључ и тајну за пријаву веб-хука у МИАДС. Додајте вебхоок УРЛ приказан на овој картици у Стрипе Девелоперс Вебхоокс, омогућите догађаје плаћања сесије плаћања, изаберите само валуте које подржава ваш Стрипе налог, а затим активирајте мрежни пролаз.',
    'billing_gateway_setup_paypal' => 'Направите РЕСТ апликацију у ПаиПал Девелопер-у за изабрани сандбок или режим уживо, а затим налепите ИД клијента и тајни кључ. Направите веб-хук са УРЛ-ом приказаном на овој картици, копирајте његов ИД веб-хука, омогућите догађаје одобреног плаћања и хватања плаћања, изаберите подржане валуте, а затим активирајте мрежни пролаз.',
    'billing_gateway_setup_bank_transfer' => 'Напишите јасна упутства за трансфер која укључују назив банке, име корисника, ИБАН или број рачуна, потребну референцу за плаћање и очекивано време прегледа. Додајте напомену клијента приказану након плаћања, омогућите само валуте које ваш банковни рачун прихвата и одобрите отпремљене признанице из налога за обрачун пре него што се претплате активирају.',
    'billing_gateway_setup_lemon_squeezy' => 'Направите Лемон Скуеези продавницу и генеричку варијанту производа за МИАДС плаћања, а затим налепите ИД продавнице, ИД варијанте, АПИ кључ и тајну веб-хука. Додајте УРЛ веб-хука приказану на овој картици у Лемон Скуеези Вебхоокс, изаберите валуте које подржава продавница, а затим активирајте мрежни пролаз.',
    'billing_gateway_setup_paddle' => 'Верификујте свој Паддле налог, креирајте производ и цену који се користе за МИАДС плаћања, а затим налепите АПИ кључ и ИД цене Паддле. Упарите сандбок или режим уживо, додајте УРЛ веб-хука приказану на овој картици под Паддле Нотифицатионс, налепите тајну веб-хука, изаберите подржане валуте, а затим активирајте мрежни пролаз.',
    'billing_gateway_setup_tabby' => 'Користите Табби само након што ваш налог трговца буде одобрен за Саудијску Арабију или УАЕ. Изаберите тачан регион, налепите јавни кључ, тајни кључ, шифру трговца и опциону тајну веб-хука, конфигуришите УРЛ веб-хука приказану на овој картици, оставите омогућене локалне подржане валуте и запамтите да чланови морају да унесу број телефона током плаћања.',
    'billing_gateway_setup_flouci' => 'Користите Флоуци за туниска плаћања у ТНД. Налепите јавни кључ и тајни кључ са свог Флоуци налога програмера, конфигуришите УРЛ веб-хука приказану на овој картици ако контролна табла вашег налога пружа подешавања веб-хука, оставите ТНД омогућен, а затим покрените малу пробну уплату пре него што је отворите члановима.',
    'billing_gateway_setup_apple_pay' => 'Аппле Паи у овом издању отвара одјаву МИАДС симулације, па унесите ИД трговца Аппле Девелопер за означавање и спремност сандбок-а. За право наплату Аппле Паи-а, довршите верификацију Аппле домена и интеграцију добављача услуга плаћања ван овог симулатора пре него што гатеваи третирате као активан.',
    'billing_apple_merchant_id_label' => 'ИД трговца',
